import React from "react";
import { Routes, Route, Link } from "react-router-dom";
import { FaSignInAlt, FaUserPlus, FaBookOpen, FaGraduationCap } from "react-icons/fa";
import Signup from "./Signup";
import Login from "./Login";
import Courses from "./Courses";

function App() {
  return (
    <div
      style={{
        minHeight: "100vh",
        background: "linear-gradient(135deg, #e0f7fa, #f3e5f5)",
        fontFamily: "Arial, sans-serif",
      }}
    >
      <nav
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          padding: "18px 40px",
          background: "#ffffff",
          boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: "10px",
            fontSize: "24px",
            fontWeight: "bold",
            color: "#4a148c",
          }}
        >
          <FaGraduationCap />
          LMS Platform
        </div>

        <div style={{ display: "flex", gap: "20px" }}>
          <Link
            to="/"
            style={{
              textDecoration: "none",
              color: "#333",
              fontWeight: "bold",
              display: "flex",
              alignItems: "center",
              gap: "6px",
            }}
          >
            <FaSignInAlt />
            Login
          </Link>

          <Link
            to="/signup"
            style={{
              textDecoration: "none",
              color: "#333",
              fontWeight: "bold",
              display: "flex",
              alignItems: "center",
              gap: "6px",
            }}
          >
            <FaUserPlus />
            Signup
          </Link>

          <Link
            to="/courses"
            style={{
              textDecoration: "none",
              color: "#333",
              fontWeight: "bold",
              display: "flex",
              alignItems: "center",
              gap: "6px",
            }}
          >
            <FaBookOpen />
            Courses
          </Link>
        </div>
      </nav>

      <div
        style={{
          maxWidth: "1100px",
          margin: "30px auto",
          padding: "20px",
        }}
      >
        <div
          style={{
            background: "#ffffff",
            borderRadius: "18px",
            boxShadow: "0 8px 25px rgba(0,0,0,0.1)",
            padding: "30px",
          }}
        >
          <Routes>
            <Route path="/" element={<Login />} />
            <Route path="/signup" element={<Signup />} />
            <Route path="/courses" element={<Courses />} />
          </Routes>
        </div>
      </div>
    </div>
  );
}

export default App;
